plugins.payload:
// Lucifer Donghua (luciferdonghua.in): Chinese animation (donghua) with English subtitles burnt in, from a site
// built on the AnimeStream WordPress theme. Videos come from OK.ru and Rumble (the sites'
// Dailymotion players are left out: Dailymotion refuses their streams to apps).
//
// Donghua sites often number all seasons in one run (season 2 episode 1 = episode 53). When the
// site has no entry of its own for the season asked, the episodes before it are counted on AniList
// and the shared entry is renumbered, so season 2 episode 45 plays the site's episode 97.

class Provider {
  constructor() {
    this.base = "https://luciferdonghua.in";
  }

  getSettings() {
    return {
      episodeServers: ["OK.ru", "Rumble"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // These sites carry subtitled releases only.
    if (opts && opts.dub) return [];
    const media = (opts && opts.media) || {};
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    let hits = [];
    let failure = null;
    for (const query of queries) {
      try {
        const html = await this._page(this.base + "/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
        for (const hit of this._searchHits(html)) {
          if (!hits.some(function (h) { return h.path === hit.path; })) hits.push(hit);
        }
      } catch (error) {
        failure = error;
      }
      if (hits.length > 0) break;
    }
    if (hits.length === 0 && failure) throw failure;

    // Episodes of the seasons before this one (-1 when AniList could not tell) and this season's
    // own count (0 when unknown): every id carries both, so the episode list can be numbered
    // the way AniList numbers this season.
    const earlier = await this._earlierEpisodes(media.id).catch(function () { return -1; });
    const limit = media.episodeCount > 0 ? media.episodeCount : 0;
    const idOf = (path, shared) => path + "@" + earlier + "@" + limit + "@" + (shared ? 1 : 0);

    const results = [];
    for (const hit of hits) {
      results.push({
        id: idOf(hit.path, false),
        title: this._cleanTitle(hit.title),
        altTitles: [hit.title],
        url: this.base + "/" + hit.path + "/",
        subOrDub: "sub",
        format: /movie/i.test(hit.type || "") ? "MOVIE" : undefined,
      });
    }

    // A later season the site keeps inside one shared entry: offered under the season's own
    // title once the shared entry is seen to go past the earlier seasons.
    const season = this._season(media);
    if (season.number > 1 && !hits.some((h) => this._seasonOf(h.title) === season.number)) {
      if (earlier > 0) {
        for (const hit of hits) {
          if (this._seasonOf(hit.title) !== 0 || /movie/i.test(hit.type || "")) continue;
          if (!this._sameShow(hit.title, season.base)) continue;
          let list;
          try {
            list = await this._episodeList(hit.path);
          } catch (error) {
            continue;
          }
          // All seasons in one run: its numbers go from the earlier seasons into this one (some
          // sites list only their last 50 episodes, so it need not start at 1).
          if (this._firstNumber(list) > earlier || this._lastNumber(list) <= earlier) continue;
          results.unshift({
            id: idOf(hit.path, true),
            title: media.englishTitle || media.romajiTitle || this._cleanTitle(hit.title),
            altTitles: [media.romajiTitle, hit.title].filter(Boolean),
            url: this.base + "/" + hit.path + "/",
            subOrDub: "sub",
          });
          break;
        }
      }
    }
    return results;
  }

  async findEpisodes(id) {
    // `path@earlier@limit@shared`: see search().
    const parts = String(id).split("@");
    const path = parts[0];
    const earlier = parts.length > 1 ? Number(parts[1]) : -1;
    const limit = parts.length > 2 ? Number(parts[2]) || 0 : 0;
    const shared = parts[3] === "1";
    if (!/^[\w\/.-]+$/.test(path)) throw new Error("invalid anime id '" + id + "'");

    const list = await this._episodeList(path);
    // Sites cut seasons in different places, so an absolute number ("Episode 51 [181]") is the
    // safe one, counted against the episodes AniList puts before this season. A list numbered
    // two ways is matched only when every absolute number lies past those episodes; otherwise
    // the site cut its season elsewhere, or AniList counts specials the site leaves out, and
    // which one cannot be told: better no episode from this site than the wrong one.
    const absolutes = list.filter(function (ep) { return ep.absolute > 0; });
    const twoWays = absolutes.some(function (ep) { return ep.absolute !== ep.relative; });
    if (twoWays && earlier < 0) {
      throw new Error("AniList did not answer, so this site's season numbering cannot be checked right now");
    }
    if (twoWays && absolutes.some(function (ep) { return ep.absolute <= earlier; })) {
      throw new Error("this site's season does not line up with AniList's");
    }
    const byAbsolute = twoWays;
    const episodes = [];
    const seen = {};
    for (const ep of list) {
      let number;
      if (byAbsolute && ep.absolute > 0) number = ep.absolute - earlier;
      // The entry added for a later season holds every season, numbered from the first.
      else if (shared && earlier > 0) number = ep.number - earlier;
      else number = ep.relative > 0 ? ep.relative : ep.number;
      if (!(number > 0) || seen[number]) continue;
      if (limit > 0 && number > limit) continue;
      seen[number] = true;
      episodes.push({
        id: ep.url,
        number: number,
        url: ep.url,
        title: ep.title || ("Episode " + number),
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const url = String((episode && (episode.url || episode.id)) || "");
    if (!/^https:\/\//.test(url)) throw new Error("no page for this episode");
    const html = await this._page(url, this.base + "/");
    const wanted = String(server || "OK.ru");
    const players = await this._players(html, url, wanted);
    const matching = players.filter(function (p) { return p.server === wanted; });
    if (matching.length === 0) throw new Error("no " + wanted + " player for this episode");

    let failure = null;
    for (const player of matching) {
      try {
        if (player.server === "OK.ru") return await this._okru(player.target);
        if (player.server === "Rumble") return await this._rumble(player.target, url);
      } catch (error) {
        failure = error;
      }
    }
    throw failure || new Error("no playable " + wanted + " video");
  }

  // ---------------------------------------------------------------- site pages

  _searchHits(html) {
    const hits = [];
    const re = /<article class="bs"[\s\S]*?<\/article>/g;
    let m;
    while ((m = re.exec(html))) {
      const block = m[0];
      const href = /href="([^"]+)"/.exec(block);
      const title = /title="([^"]+)"/.exec(block) || /<h2[^>]*>([\s\S]*?)<\/h2>/.exec(block);
      const type = /<div class="typez[^"]*">([\s\S]*?)<\/div>/.exec(block);
      if (!href || !title) continue;
      const path = this._path(href[1]);
      if (!path) continue;
      // Motion comics share the show's name but are not the show.
      if (/\bcomics?\b|manhua\s*animation/i.test(title[1])) continue;
      hits.push({ path: path, title: this._plain(title[1]), type: type ? this._plain(type[1]) : "" });
    }
    return hits;
  }

  async _episodeList(path) {
    const html = await this._page(this.base + "/" + path + "/", this.base + "/");
    const box = /<div class="eplister">([\s\S]*?)<\/ul>/.exec(html);
    if (!box) throw new Error("no episodes listed");
    const list = [];
    const re = /<li[^>]*>\s*<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(box[1]))) {
      const num = /class="epl-num">([\s\S]*?)<\/div>/.exec(m[2]);
      const title = /class="epl-title">([\s\S]*?)<\/div>/.exec(m[2]);
      const number = num ? this._leadingNumber(this._plain(num[1])) : NaN;
      if (!isFinite(number)) continue;
      const name = title ? this._plain(title[1]) : "";
      // "Episode 51 [181]": 51 in the season, 181 counted from the show's first episode.
      const both = /\bEp(?:isode|isod|s)?\.?\s*0*(\d+)\s*\[0*(\d+)\]/i.exec(name);
      list.push({
        url: this._absolute(m[1]),
        number: number,
        relative: both ? Number(both[1]) : 0,
        absolute: both ? Number(both[2]) : 0,
        title: name,
      });
    }
    if (list.length === 0) throw new Error("no episodes listed");
    return list;
  }

  // The players of an episode page for one server: { server, target, label }, English ones
  // first; players with Indonesian subtitles only are left out (they would pass as English).
  async _players(html, pageUrl, wanted) {
    const options = [];
    const re = /<option[^>]*value="([^"]+)"[^>]*>([\s\S]*?)<\/option>/g;
    let m;
    while ((m = re.exec(html))) options.push({ value: this._unescapeBody(m[1]), label: this._plain(m[2]) });
    // Other sites give each player as a button: `data-server="…" data-embed="<base64 iframe>"`.
    const buttons = /<a[^>]*data-embed="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    while ((m = buttons.exec(html))) options.push({ value: m[1], label: this._plain(m[2]) });

    // A player on a page of its own (`…/v/2/`) is loaded only when its label names the server
    // asked for, or when no label names any known server.
    const names = { "OK.ru": /ok\.?\s*ru/i, Rumble: /rumb/i };
    const named = options.some(function (o) { return names["OK.ru"].test(o.label) || names.Rumble.test(o.label); });
    const players = [];
    for (const option of options) {
      let embed = "";
      if (/^https?:\/\//i.test(option.value)) {
        if (option.value.indexOf(this.base) !== 0) continue;
        if (named && names[wanted] && !names[wanted].test(option.label)) continue;
        try {
          embed = await this._page(option.value, pageUrl);
        } catch (error) {
          continue;
        }
        const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(embed) || /<div id="pembed"[^>]*>([\s\S]*?)<\/div>/.exec(embed);
        if (box) embed = box[1];
      } else {
        try {
          embed = atob(option.value.replace(/\s+/g, ""));
        } catch (error) {
          continue;
        }
      }
      const player = this._identify(embed);
      if (player) {
        player.label = option.label;
        players.push(player);
      }
    }
    if (players.length === 0) {
      const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(html);
      const player = box ? this._identify(box[1]) : null;
      if (player) players.push(player);
    }
    // English subtitles first; players with Indonesian subtitles only come last.
    const rank = function (p) {
      const label = String(p.label || "");
      if (/eng|multi|all\s*sub/i.test(label)) return 0;
      if (/indo|indonesia/i.test(label)) return 2;
      return 1;
    };
    const kept = players.filter(function (p) { return p.server === wanted && rank(p) < 2; });
    kept.sort(function (a, b) { return rank(a) - rank(b); });
    return kept;
  }

  _identify(embed) {
    const text = String(embed);
    let m = /ok\.ru\/videoembed\/(\d+)/.exec(text);
    if (m) return { server: "OK.ru", target: m[1] };
    m = /rumble\.com\/embed\/([\w]+)/.exec(text);
    if (m) return { server: "Rumble", target: m[1] };
    return null;
  }

  // ---------------------------------------------------------------- video hosts

  async _okru(id) {
    const html = await this._page("https://ok.ru/videoembed/" + id, "https://ok.ru/");
    const m = /data-options="([^"]+)"/.exec(html);
    if (!m) throw new Error("OK.ru video unavailable");
    const options = JSON.parse(this._unescapeBody(m[1]));
    let meta = options && options.flashvars && options.flashvars.metadata;
    if (typeof meta === "string") meta = JSON.parse(meta);
    if (!meta) throw new Error("OK.ru video unavailable");
    const sources = [];
    if (meta.hlsManifestUrl) sources.push({ url: meta.hlsManifestUrl, type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] });
    const order = ["ultra", "quad", "full", "hd", "sd", "low"];
    const names = { ultra: "2160p", quad: "1440p", full: "1080p", hd: "720p", sd: "480p", low: "360p" };
    const videos = (meta.videos || []).filter(function (v) { return v && v.url && order.indexOf(v.name) >= 0; });
    videos.sort(function (a, b) { return order.indexOf(a.name) - order.indexOf(b.name); });
    for (const v of videos.slice(0, 2)) sources.push({ url: v.url, type: "mp4", quality: names[v.name], label: "English hard sub", subtitles: [] });
    if (sources.length === 0) throw new Error("OK.ru has no stream for this video");
    return { server: "OK.ru", headers: { Referer: "https://ok.ru/" }, videoSources: sources };
  }

  async _rumble(id, pageUrl) {
    const html = this._unescapeBody(await this._page("https://rumble.com/embed/" + id + "/", pageUrl));
    const m = /"hls":\{(?:"auto":\{)?"url":"([^"]+\.m3u8[^"]*)"/.exec(html);
    if (!m) throw new Error("Rumble video unavailable");
    return {
      server: "Rumble",
      headers: { Referer: "https://rumble.com/" },
      videoSources: [{ url: m[1], type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] }],
    };
  }

  // ---------------------------------------------------------------- seasons

  // Episodes of the seasons before this one on AniList (prequels of the same kind, followed
  // back), kept for the session. AniList answers relations two levels deep only, so each request
  // walks two seasons back. Throws when AniList cannot tell, so the site's own numbers are used
  // instead of a guess.
  async _earlierEpisodes(anilistId) {
    const first = Number(anilistId);
    if (!(first > 0)) throw new Error("no AniList id");
    this._earlierKnown = this._earlierKnown || {};
    this._earlierFailed = this._earlierFailed || {};
    if (this._earlierKnown[first] !== undefined) return this._earlierKnown[first];
    if (this._earlierFailed[first] && Date.now() - this._earlierFailed[first] < 60000) {
      throw new Error("AniList did not answer a moment ago");
    }
    try {
      const total = await this._askEarlier(first);
      this._earlierKnown[first] = total;
      return total;
    } catch (error) {
      this._earlierFailed[first] = Date.now();
      throw error;
    }
  }

  async _askEarlier(first) {

    const isPrequel = function (e) {
      return e.relationType === "PREQUEL" && e.node && e.node.type === "ANIME" && /^(TV|ONA|TV_SHORT)$/.test(e.node.format || "");
    };
    const edges = "relations{edges{relationType node{id type format episodes ";
    const query = "query($id:Int){Media(id:$id){id " + edges + edges + "id}}}}}}}}";
    let id = first;
    let total = 0;
    for (let request = 0; request < 5; request++) {
      const response = await fetch("https://graphql.anilist.co", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ query: query, variables: { id: id } }),
      });
      if (!response.ok) throw new Error("AniList answered HTTP " + response.status);
      const data = JSON.parse(String(await response.text()));
      const media = data && data.data && data.data.Media;
      if (!media || !media.relations) throw new Error("AniList has no entry " + id);

      const one = (media.relations.edges || []).find(isPrequel);
      if (!one) return total;
      if (!(one.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += one.node.episodes;
      if (!one.node.relations) throw new Error("AniList left out a season's relations");
      const two = (one.node.relations.edges || []).find(isPrequel);
      if (!two) return total;
      if (!(two.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += two.node.episodes;
      // Its own prequels were not asked for: the next request starts from it.
      id = two.node.id;
    }
    throw new Error("too many seasons before this one");
  }

  _season(media) {
    let number = 1;
    let base = "";
    for (const title of [media.englishTitle, media.romajiTitle]) {
      if (typeof title !== "string" || !title) continue;
      const n = this._seasonOf(title);
      if (n > number) number = n;
      if (!base) base = this._withoutSeason(title);
    }
    return { number: number, base: base };
  }

  // Season a title names: "Season 2", "2nd Season", "S2", a trailing " 2"; 0 when it names none.
  _seasonOf(title) {
    const t = String(title).toLowerCase();
    let m = /\bseason\s*(\d+)\b/.exec(t) || /\b(\d+)(?:st|nd|rd|th)\s+season\b/.exec(t) || /\bs(\d+)\b/.exec(t);
    if (m) return Number(m[1]);
    m = /\s(\d)\s*$/.exec(t.replace(/\(\d{4}\)/g, "").replace(/\[[^\]]*\]/g, "").trim());
    if (m) return Number(m[1]);
    return 0;
  }

  _withoutSeason(title) {
    return String(title)
      .replace(/\b(?:season\s*\d+|\d+(?:st|nd|rd|th)\s+season|s\d+|part\s*\d+|cour\s*\d+)\b/gi, " ")
      .replace(/\s\d\s*$/, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _sameShow(siteTitle, base) {
    const words = function (s) {
      return String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").split(" ").filter(function (w) {
        return w && ["the", "of", "a", "3d", "season"].indexOf(w) < 0;
      });
    };
    const want = words(base);
    const got = words(this._cleanTitle(siteTitle));
    if (want.length === 0 || want.length !== got.length) return false;
    return want.every(function (w) { return got.indexOf(w) >= 0; });
  }

  _firstNumber(list) {
    let first = Infinity;
    for (const ep of list) if (ep.number < first) first = ep.number;
    return first;
  }

  _lastNumber(list) {
    let last = 0;
    for (const ep of list) if (ep.number > last) last = ep.number;
    return last;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const add = (title) => {
      if (typeof title !== "string") return;
      const plain = this._withoutSeason(title.replace(/\(\d{4}\)/g, " ").replace(/[^\w\s'-]+/g, " ")).replace(/\s+/g, " ").trim();
      if (plain && queries.indexOf(plain) < 0) queries.push(plain);
    };
    // The app calls search once per title it knows, so the title it gives is the one searched.
    add(opts && opts.query);
    if (queries.length === 0) {
      add(media.englishTitle);
      add(media.romajiTitle);
    }
    // These sites find only titles holding every word searched ("Tang Clan" misses "Tang Sect"):
    // the first words alone come next, and the app picks the right hit among them.
    const words = (queries[0] || "").split(" ");
    if (words.length > 3) add(words.slice(0, 3).join(" "));
    return queries.slice(0, 2);
  }

  // A site title without what only the site adds: "(2023)", "[Da Zhuzai]", "3D", "Subbed"…
  _cleanTitle(title) {
    return String(title)
      .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
      .replace(/\b(?:3d|subbed|eng(?:lish)?\s*sub|multi(?:ple)?\s*sub(?:titles?)?|subtitle\s*indonesia|indo(?:nesia)?\s*sub)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _leadingNumber(text) {
    const m = /^\s*(\d+(?:\.\d+)?)/.exec(String(text));
    return m ? Number(m[1]) : NaN;
  }

  _path(href) {
    const url = this._absolute(href);
    if (url.indexOf(this.base + "/") !== 0) return "";
    return url.slice(this.base.length + 1).replace(/\/+$/, "");
  }

  _absolute(href) {
    const text = String(href).trim();
    if (/^https?:\/\//i.test(text)) return text.replace(/^http:/i, "https:");
    if (text.indexOf("//") === 0) return "https:" + text;
    return this.base + (text.charAt(0) === "/" ? "" : "/") + text;
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl-bypass", "challenge-platform/h/b/orchestrate", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  async _page(url, referer) {
    const host = this._host(url);
    const headers = {};
    if (referer) headers.Referer = referer;
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (text.length < 20000 && this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
    return text;
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}

// AnimeKhor (animekhor.org): Chinese animation (donghua) with English subtitles burnt in, from a site
// built on the AnimeStream WordPress theme. Videos come from OK.ru and Rumble (the sites'
// Dailymotion players are left out: Dailymotion refuses their streams to apps).
//
// Donghua sites often number all seasons in one run (season 2 episode 1 = episode 53). When the
// site has no entry of its own for the season asked, the episodes before it are counted on AniList
// and the shared entry is renumbered, so season 2 episode 45 plays the site's episode 97.

class Provider {
  constructor() {
    this.base = "https://animekhor.org";
  }

  getSettings() {
    return {
      episodeServers: ["OK.ru", "Rumble"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // These sites carry subtitled releases only.
    if (opts && opts.dub) return [];
    const media = (opts && opts.media) || {};
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    let hits = [];
    let failure = null;
    for (const query of queries) {
      try {
        const html = await this._page(this.base + "/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
        for (const hit of this._searchHits(html)) {
          if (!hits.some(function (h) { return h.path === hit.path; })) hits.push(hit);
        }
      } catch (error) {
        failure = error;
      }
      if (hits.length > 0) break;
    }
    if (hits.length === 0 && failure) throw failure;

    // Episodes of the seasons before this one (-1 when AniList could not tell) and this season's
    // own count (0 when unknown): every id carries both, so the episode list can be numbered
    // the way AniList numbers this season.
    const earlier = await this._earlierEpisodes(media.id).catch(function () { return -1; });
    const limit = media.episodeCount > 0 ? media.episodeCount : 0;
    const idOf = (path, shared) => path + "@" + earlier + "@" + limit + "@" + (shared ? 1 : 0);

    const results = [];
    for (const hit of hits) {
      results.push({
        id: idOf(hit.path, false),
        title: this._cleanTitle(hit.title),
        altTitles: [hit.title],
        url: this.base + "/" + hit.path + "/",
        subOrDub: "sub",
        format: /movie/i.test(hit.type || "") ? "MOVIE" : undefined,
      });
    }

    // A later season the site keeps inside one shared entry: offered under the season's own
    // title once the shared entry is seen to go past the earlier seasons.
    const season = this._season(media);
    if (season.number > 1 && !hits.some((h) => this._seasonOf(h.title) === season.number)) {
      if (earlier > 0) {
        for (const hit of hits) {
          if (this._seasonOf(hit.title) !== 0 || /movie/i.test(hit.type || "")) continue;
          if (!this._sameShow(hit.title, season.base)) continue;
          let list;
          try {
            list = await this._episodeList(hit.path);
          } catch (error) {
            continue;
          }
          // All seasons in one run: its numbers go from the earlier seasons into this one (some
          // sites list only their last 50 episodes, so it need not start at 1).
          if (this._firstNumber(list) > earlier || this._lastNumber(list) <= earlier) continue;
          results.unshift({
            id: idOf(hit.path, true),
            title: media.englishTitle || media.romajiTitle || this._cleanTitle(hit.title),
            altTitles: [media.romajiTitle, hit.title].filter(Boolean),
            url: this.base + "/" + hit.path + "/",
            subOrDub: "sub",
          });
          break;
        }
      }
    }
    return results;
  }

  async findEpisodes(id) {
    // `path@earlier@limit@shared`: see search().
    const parts = String(id).split("@");
    const path = parts[0];
    const earlier = parts.length > 1 ? Number(parts[1]) : -1;
    const limit = parts.length > 2 ? Number(parts[2]) || 0 : 0;
    const shared = parts[3] === "1";
    if (!/^[\w\/.-]+$/.test(path)) throw new Error("invalid anime id '" + id + "'");

    const list = await this._episodeList(path);
    // Sites cut seasons in different places, so an absolute number ("Episode 51 [181]") is the
    // safe one, counted against the episodes AniList puts before this season. A list numbered
    // two ways is matched only when every absolute number lies past those episodes; otherwise
    // the site cut its season elsewhere, or AniList counts specials the site leaves out, and
    // which one cannot be told: better no episode from this site than the wrong one.
    const absolutes = list.filter(function (ep) { return ep.absolute > 0; });
    const twoWays = absolutes.some(function (ep) { return ep.absolute !== ep.relative; });
    if (twoWays && earlier < 0) {
      throw new Error("AniList did not answer, so this site's season numbering cannot be checked right now");
    }
    if (twoWays && absolutes.some(function (ep) { return ep.absolute <= earlier; })) {
      throw new Error("this site's season does not line up with AniList's");
    }
    const byAbsolute = twoWays;
    const episodes = [];
    const seen = {};
    for (const ep of list) {
      let number;
      if (byAbsolute && ep.absolute > 0) number = ep.absolute - earlier;
      // The entry added for a later season holds every season, numbered from the first.
      else if (shared && earlier > 0) number = ep.number - earlier;
      else number = ep.relative > 0 ? ep.relative : ep.number;
      if (!(number > 0) || seen[number]) continue;
      if (limit > 0 && number > limit) continue;
      seen[number] = true;
      episodes.push({
        id: ep.url,
        number: number,
        url: ep.url,
        title: ep.title || ("Episode " + number),
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const url = String((episode && (episode.url || episode.id)) || "");
    if (!/^https:\/\//.test(url)) throw new Error("no page for this episode");
    const html = await this._page(url, this.base + "/");
    const wanted = String(server || "OK.ru");
    const players = await this._players(html, url, wanted);
    const matching = players.filter(function (p) { return p.server === wanted; });
    if (matching.length === 0) throw new Error("no " + wanted + " player for this episode");

    let failure = null;
    for (const player of matching) {
      try {
        if (player.server === "OK.ru") return await this._okru(player.target);
        if (player.server === "Rumble") return await this._rumble(player.target, url);
      } catch (error) {
        failure = error;
      }
    }
    throw failure || new Error("no playable " + wanted + " video");
  }

  // ---------------------------------------------------------------- site pages

  _searchHits(html) {
    const hits = [];
    const re = /<article class="bs"[\s\S]*?<\/article>/g;
    let m;
    while ((m = re.exec(html))) {
      const block = m[0];
      const href = /href="([^"]+)"/.exec(block);
      const title = /title="([^"]+)"/.exec(block) || /<h2[^>]*>([\s\S]*?)<\/h2>/.exec(block);
      const type = /<div class="typez[^"]*">([\s\S]*?)<\/div>/.exec(block);
      if (!href || !title) continue;
      const path = this._path(href[1]);
      if (!path) continue;
      // Motion comics share the show's name but are not the show.
      if (/\bcomics?\b|manhua\s*animation/i.test(title[1])) continue;
      hits.push({ path: path, title: this._plain(title[1]), type: type ? this._plain(type[1]) : "" });
    }
    return hits;
  }

  async _episodeList(path) {
    const html = await this._page(this.base + "/" + path + "/", this.base + "/");
    const box = /<div class="eplister">([\s\S]*?)<\/ul>/.exec(html);
    if (!box) throw new Error("no episodes listed");
    const list = [];
    const re = /<li[^>]*>\s*<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(box[1]))) {
      const num = /class="epl-num">([\s\S]*?)<\/div>/.exec(m[2]);
      const title = /class="epl-title">([\s\S]*?)<\/div>/.exec(m[2]);
      const number = num ? this._leadingNumber(this._plain(num[1])) : NaN;
      if (!isFinite(number)) continue;
      const name = title ? this._plain(title[1]) : "";
      // "Episode 51 [181]": 51 in the season, 181 counted from the show's first episode.
      const both = /\bEp(?:isode|isod|s)?\.?\s*0*(\d+)\s*\[0*(\d+)\]/i.exec(name);
      list.push({
        url: this._absolute(m[1]),
        number: number,
        relative: both ? Number(both[1]) : 0,
        absolute: both ? Number(both[2]) : 0,
        title: name,
      });
    }
    if (list.length === 0) throw new Error("no episodes listed");
    return list;
  }

  // The players of an episode page for one server: { server, target, label }, English ones
  // first; players with Indonesian subtitles only are left out (they would pass as English).
  async _players(html, pageUrl, wanted) {
    const options = [];
    const re = /<option[^>]*value="([^"]+)"[^>]*>([\s\S]*?)<\/option>/g;
    let m;
    while ((m = re.exec(html))) options.push({ value: this._unescapeBody(m[1]), label: this._plain(m[2]) });
    // Other sites give each player as a button: `data-server="…" data-embed="<base64 iframe>"`.
    const buttons = /<a[^>]*data-embed="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    while ((m = buttons.exec(html))) options.push({ value: m[1], label: this._plain(m[2]) });

    // A player on a page of its own (`…/v/2/`) is loaded only when its label names the server
    // asked for, or when no label names any known server.
    const names = { "OK.ru": /ok\.?\s*ru/i, Rumble: /rumb/i };
    const named = options.some(function (o) { return names["OK.ru"].test(o.label) || names.Rumble.test(o.label); });
    const players = [];
    for (const option of options) {
      let embed = "";
      if (/^https?:\/\//i.test(option.value)) {
        if (option.value.indexOf(this.base) !== 0) continue;
        if (named && names[wanted] && !names[wanted].test(option.label)) continue;
        try {
          embed = await this._page(option.value, pageUrl);
        } catch (error) {
          continue;
        }
        const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(embed) || /<div id="pembed"[^>]*>([\s\S]*?)<\/div>/.exec(embed);
        if (box) embed = box[1];
      } else {
        try {
          embed = atob(option.value.replace(/\s+/g, ""));
        } catch (error) {
          continue;
        }
      }
      const player = this._identify(embed);
      if (player) {
        player.label = option.label;
        players.push(player);
      }
    }
    if (players.length === 0) {
      const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(html);
      const player = box ? this._identify(box[1]) : null;
      if (player) players.push(player);
    }
    // English subtitles first; players with Indonesian subtitles only come last.
    const rank = function (p) {
      const label = String(p.label || "");
      if (/eng|multi|all\s*sub/i.test(label)) return 0;
      if (/indo|indonesia/i.test(label)) return 2;
      return 1;
    };
    const kept = players.filter(function (p) { return p.server === wanted && rank(p) < 2; });
    kept.sort(function (a, b) { return rank(a) - rank(b); });
    return kept;
  }

  _identify(embed) {
    const text = String(embed);
    let m = /ok\.ru\/videoembed\/(\d+)/.exec(text);
    if (m) return { server: "OK.ru", target: m[1] };
    m = /rumble\.com\/embed\/([\w]+)/.exec(text);
    if (m) return { server: "Rumble", target: m[1] };
    return null;
  }

  // ---------------------------------------------------------------- video hosts

  async _okru(id) {
    const html = await this._page("https://ok.ru/videoembed/" + id, "https://ok.ru/");
    const m = /data-options="([^"]+)"/.exec(html);
    if (!m) throw new Error("OK.ru video unavailable");
    const options = JSON.parse(this._unescapeBody(m[1]));
    let meta = options && options.flashvars && options.flashvars.metadata;
    if (typeof meta === "string") meta = JSON.parse(meta);
    if (!meta) throw new Error("OK.ru video unavailable");
    const sources = [];
    if (meta.hlsManifestUrl) sources.push({ url: meta.hlsManifestUrl, type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] });
    const order = ["ultra", "quad", "full", "hd", "sd", "low"];
    const names = { ultra: "2160p", quad: "1440p", full: "1080p", hd: "720p", sd: "480p", low: "360p" };
    const videos = (meta.videos || []).filter(function (v) { return v && v.url && order.indexOf(v.name) >= 0; });
    videos.sort(function (a, b) { return order.indexOf(a.name) - order.indexOf(b.name); });
    for (const v of videos.slice(0, 2)) sources.push({ url: v.url, type: "mp4", quality: names[v.name], label: "English hard sub", subtitles: [] });
    if (sources.length === 0) throw new Error("OK.ru has no stream for this video");
    return { server: "OK.ru", headers: { Referer: "https://ok.ru/" }, videoSources: sources };
  }

  async _rumble(id, pageUrl) {
    const html = this._unescapeBody(await this._page("https://rumble.com/embed/" + id + "/", pageUrl));
    const m = /"hls":\{(?:"auto":\{)?"url":"([^"]+\.m3u8[^"]*)"/.exec(html);
    if (!m) throw new Error("Rumble video unavailable");
    return {
      server: "Rumble",
      headers: { Referer: "https://rumble.com/" },
      videoSources: [{ url: m[1], type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] }],
    };
  }

  // ---------------------------------------------------------------- seasons

  // Episodes of the seasons before this one on AniList (prequels of the same kind, followed
  // back), kept for the session. AniList answers relations two levels deep only, so each request
  // walks two seasons back. Throws when AniList cannot tell, so the site's own numbers are used
  // instead of a guess.
  async _earlierEpisodes(anilistId) {
    const first = Number(anilistId);
    if (!(first > 0)) throw new Error("no AniList id");
    this._earlierKnown = this._earlierKnown || {};
    this._earlierFailed = this._earlierFailed || {};
    if (this._earlierKnown[first] !== undefined) return this._earlierKnown[first];
    if (this._earlierFailed[first] && Date.now() - this._earlierFailed[first] < 60000) {
      throw new Error("AniList did not answer a moment ago");
    }
    try {
      const total = await this._askEarlier(first);
      this._earlierKnown[first] = total;
      return total;
    } catch (error) {
      this._earlierFailed[first] = Date.now();
      throw error;
    }
  }

  async _askEarlier(first) {

    const isPrequel = function (e) {
      return e.relationType === "PREQUEL" && e.node && e.node.type === "ANIME" && /^(TV|ONA|TV_SHORT)$/.test(e.node.format || "");
    };
    const edges = "relations{edges{relationType node{id type format episodes ";
    const query = "query($id:Int){Media(id:$id){id " + edges + edges + "id}}}}}}}}";
    let id = first;
    let total = 0;
    for (let request = 0; request < 5; request++) {
      const response = await fetch("https://graphql.anilist.co", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ query: query, variables: { id: id } }),
      });
      if (!response.ok) throw new Error("AniList answered HTTP " + response.status);
      const data = JSON.parse(String(await response.text()));
      const media = data && data.data && data.data.Media;
      if (!media || !media.relations) throw new Error("AniList has no entry " + id);

      const one = (media.relations.edges || []).find(isPrequel);
      if (!one) return total;
      if (!(one.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += one.node.episodes;
      if (!one.node.relations) throw new Error("AniList left out a season's relations");
      const two = (one.node.relations.edges || []).find(isPrequel);
      if (!two) return total;
      if (!(two.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += two.node.episodes;
      // Its own prequels were not asked for: the next request starts from it.
      id = two.node.id;
    }
    throw new Error("too many seasons before this one");
  }

  _season(media) {
    let number = 1;
    let base = "";
    for (const title of [media.englishTitle, media.romajiTitle]) {
      if (typeof title !== "string" || !title) continue;
      const n = this._seasonOf(title);
      if (n > number) number = n;
      if (!base) base = this._withoutSeason(title);
    }
    return { number: number, base: base };
  }

  // Season a title names: "Season 2", "2nd Season", "S2", a trailing " 2"; 0 when it names none.
  _seasonOf(title) {
    const t = String(title).toLowerCase();
    let m = /\bseason\s*(\d+)\b/.exec(t) || /\b(\d+)(?:st|nd|rd|th)\s+season\b/.exec(t) || /\bs(\d+)\b/.exec(t);
    if (m) return Number(m[1]);
    m = /\s(\d)\s*$/.exec(t.replace(/\(\d{4}\)/g, "").replace(/\[[^\]]*\]/g, "").trim());
    if (m) return Number(m[1]);
    return 0;
  }

  _withoutSeason(title) {
    return String(title)
      .replace(/\b(?:season\s*\d+|\d+(?:st|nd|rd|th)\s+season|s\d+|part\s*\d+|cour\s*\d+)\b/gi, " ")
      .replace(/\s\d\s*$/, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _sameShow(siteTitle, base) {
    const words = function (s) {
      return String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").split(" ").filter(function (w) {
        return w && ["the", "of", "a", "3d", "season"].indexOf(w) < 0;
      });
    };
    const want = words(base);
    const got = words(this._cleanTitle(siteTitle));
    if (want.length === 0 || want.length !== got.length) return false;
    return want.every(function (w) { return got.indexOf(w) >= 0; });
  }

  _firstNumber(list) {
    let first = Infinity;
    for (const ep of list) if (ep.number < first) first = ep.number;
    return first;
  }

  _lastNumber(list) {
    let last = 0;
    for (const ep of list) if (ep.number > last) last = ep.number;
    return last;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const add = (title) => {
      if (typeof title !== "string") return;
      const plain = this._withoutSeason(title.replace(/\(\d{4}\)/g, " ").replace(/[^\w\s'-]+/g, " ")).replace(/\s+/g, " ").trim();
      if (plain && queries.indexOf(plain) < 0) queries.push(plain);
    };
    // The app calls search once per title it knows, so the title it gives is the one searched.
    add(opts && opts.query);
    if (queries.length === 0) {
      add(media.englishTitle);
      add(media.romajiTitle);
    }
    // These sites find only titles holding every word searched ("Tang Clan" misses "Tang Sect"):
    // the first words alone come next, and the app picks the right hit among them.
    const words = (queries[0] || "").split(" ");
    if (words.length > 3) add(words.slice(0, 3).join(" "));
    return queries.slice(0, 2);
  }

  // A site title without what only the site adds: "(2023)", "[Da Zhuzai]", "3D", "Subbed"…
  _cleanTitle(title) {
    return String(title)
      .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
      .replace(/\b(?:3d|subbed|eng(?:lish)?\s*sub|multi(?:ple)?\s*sub(?:titles?)?|subtitle\s*indonesia|indo(?:nesia)?\s*sub)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _leadingNumber(text) {
    const m = /^\s*(\d+(?:\.\d+)?)/.exec(String(text));
    return m ? Number(m[1]) : NaN;
  }

  _path(href) {
    const url = this._absolute(href);
    if (url.indexOf(this.base + "/") !== 0) return "";
    return url.slice(this.base.length + 1).replace(/\/+$/, "");
  }

  _absolute(href) {
    const text = String(href).trim();
    if (/^https?:\/\//i.test(text)) return text.replace(/^http:/i, "https:");
    if (text.indexOf("//") === 0) return "https:" + text;
    return this.base + (text.charAt(0) === "/" ? "" : "/") + text;
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl-bypass", "challenge-platform/h/b/orchestrate", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  async _page(url, referer) {
    const host = this._host(url);
    const headers = {};
    if (referer) headers.Referer = referer;
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (text.length < 20000 && this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
    return text;
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}

// DonghuaStream (donghuastream.org): Chinese animation (donghua) with English subtitles burnt in, from a site
// built on the AnimeStream WordPress theme. Videos come from OK.ru and Rumble (the sites'
// Dailymotion players are left out: Dailymotion refuses their streams to apps).
//
// Donghua sites often number all seasons in one run (season 2 episode 1 = episode 53). When the
// site has no entry of its own for the season asked, the episodes before it are counted on AniList
// and the shared entry is renumbered, so season 2 episode 45 plays the site's episode 97.

class Provider {
  constructor() {
    this.base = "https://donghuastream.org";
  }

  getSettings() {
    return {
      episodeServers: ["OK.ru", "Rumble"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // These sites carry subtitled releases only.
    if (opts && opts.dub) return [];
    const media = (opts && opts.media) || {};
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    let hits = [];
    let failure = null;
    for (const query of queries) {
      try {
        const html = await this._page(this.base + "/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
        for (const hit of this._searchHits(html)) {
          if (!hits.some(function (h) { return h.path === hit.path; })) hits.push(hit);
        }
      } catch (error) {
        failure = error;
      }
      if (hits.length > 0) break;
    }
    if (hits.length === 0 && failure) throw failure;

    // Episodes of the seasons before this one (-1 when AniList could not tell) and this season's
    // own count (0 when unknown): every id carries both, so the episode list can be numbered
    // the way AniList numbers this season.
    const earlier = await this._earlierEpisodes(media.id).catch(function () { return -1; });
    const limit = media.episodeCount > 0 ? media.episodeCount : 0;
    const idOf = (path, shared) => path + "@" + earlier + "@" + limit + "@" + (shared ? 1 : 0);

    const results = [];
    for (const hit of hits) {
      results.push({
        id: idOf(hit.path, false),
        title: this._cleanTitle(hit.title),
        altTitles: [hit.title],
        url: this.base + "/" + hit.path + "/",
        subOrDub: "sub",
        format: /movie/i.test(hit.type || "") ? "MOVIE" : undefined,
      });
    }

    // A later season the site keeps inside one shared entry: offered under the season's own
    // title once the shared entry is seen to go past the earlier seasons.
    const season = this._season(media);
    if (season.number > 1 && !hits.some((h) => this._seasonOf(h.title) === season.number)) {
      if (earlier > 0) {
        for (const hit of hits) {
          if (this._seasonOf(hit.title) !== 0 || /movie/i.test(hit.type || "")) continue;
          if (!this._sameShow(hit.title, season.base)) continue;
          let list;
          try {
            list = await this._episodeList(hit.path);
          } catch (error) {
            continue;
          }
          // All seasons in one run: its numbers go from the earlier seasons into this one (some
          // sites list only their last 50 episodes, so it need not start at 1).
          if (this._firstNumber(list) > earlier || this._lastNumber(list) <= earlier) continue;
          results.unshift({
            id: idOf(hit.path, true),
            title: media.englishTitle || media.romajiTitle || this._cleanTitle(hit.title),
            altTitles: [media.romajiTitle, hit.title].filter(Boolean),
            url: this.base + "/" + hit.path + "/",
            subOrDub: "sub",
          });
          break;
        }
      }
    }
    return results;
  }

  async findEpisodes(id) {
    // `path@earlier@limit@shared`: see search().
    const parts = String(id).split("@");
    const path = parts[0];
    const earlier = parts.length > 1 ? Number(parts[1]) : -1;
    const limit = parts.length > 2 ? Number(parts[2]) || 0 : 0;
    const shared = parts[3] === "1";
    if (!/^[\w\/.-]+$/.test(path)) throw new Error("invalid anime id '" + id + "'");

    const list = await this._episodeList(path);
    // Sites cut seasons in different places, so an absolute number ("Episode 51 [181]") is the
    // safe one, counted against the episodes AniList puts before this season. A list numbered
    // two ways is matched only when every absolute number lies past those episodes; otherwise
    // the site cut its season elsewhere, or AniList counts specials the site leaves out, and
    // which one cannot be told: better no episode from this site than the wrong one.
    const absolutes = list.filter(function (ep) { return ep.absolute > 0; });
    const twoWays = absolutes.some(function (ep) { return ep.absolute !== ep.relative; });
    if (twoWays && earlier < 0) {
      throw new Error("AniList did not answer, so this site's season numbering cannot be checked right now");
    }
    if (twoWays && absolutes.some(function (ep) { return ep.absolute <= earlier; })) {
      throw new Error("this site's season does not line up with AniList's");
    }
    const byAbsolute = twoWays;
    const episodes = [];
    const seen = {};
    for (const ep of list) {
      let number;
      if (byAbsolute && ep.absolute > 0) number = ep.absolute - earlier;
      // The entry added for a later season holds every season, numbered from the first.
      else if (shared && earlier > 0) number = ep.number - earlier;
      else number = ep.relative > 0 ? ep.relative : ep.number;
      if (!(number > 0) || seen[number]) continue;
      if (limit > 0 && number > limit) continue;
      seen[number] = true;
      episodes.push({
        id: ep.url,
        number: number,
        url: ep.url,
        title: ep.title || ("Episode " + number),
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const url = String((episode && (episode.url || episode.id)) || "");
    if (!/^https:\/\//.test(url)) throw new Error("no page for this episode");
    const html = await this._page(url, this.base + "/");
    const wanted = String(server || "OK.ru");
    const players = await this._players(html, url, wanted);
    const matching = players.filter(function (p) { return p.server === wanted; });
    if (matching.length === 0) throw new Error("no " + wanted + " player for this episode");

    let failure = null;
    for (const player of matching) {
      try {
        if (player.server === "OK.ru") return await this._okru(player.target);
        if (player.server === "Rumble") return await this._rumble(player.target, url);
      } catch (error) {
        failure = error;
      }
    }
    throw failure || new Error("no playable " + wanted + " video");
  }

  // ---------------------------------------------------------------- site pages

  _searchHits(html) {
    const hits = [];
    const re = /<article class="bs"[\s\S]*?<\/article>/g;
    let m;
    while ((m = re.exec(html))) {
      const block = m[0];
      const href = /href="([^"]+)"/.exec(block);
      const title = /title="([^"]+)"/.exec(block) || /<h2[^>]*>([\s\S]*?)<\/h2>/.exec(block);
      const type = /<div class="typez[^"]*">([\s\S]*?)<\/div>/.exec(block);
      if (!href || !title) continue;
      const path = this._path(href[1]);
      if (!path) continue;
      // Motion comics share the show's name but are not the show.
      if (/\bcomics?\b|manhua\s*animation/i.test(title[1])) continue;
      hits.push({ path: path, title: this._plain(title[1]), type: type ? this._plain(type[1]) : "" });
    }
    return hits;
  }

  async _episodeList(path) {
    const html = await this._page(this.base + "/" + path + "/", this.base + "/");
    const box = /<div class="eplister">([\s\S]*?)<\/ul>/.exec(html);
    if (!box) throw new Error("no episodes listed");
    const list = [];
    const re = /<li[^>]*>\s*<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(box[1]))) {
      const num = /class="epl-num">([\s\S]*?)<\/div>/.exec(m[2]);
      const title = /class="epl-title">([\s\S]*?)<\/div>/.exec(m[2]);
      const number = num ? this._leadingNumber(this._plain(num[1])) : NaN;
      if (!isFinite(number)) continue;
      const name = title ? this._plain(title[1]) : "";
      // "Episode 51 [181]": 51 in the season, 181 counted from the show's first episode.
      const both = /\bEp(?:isode|isod|s)?\.?\s*0*(\d+)\s*\[0*(\d+)\]/i.exec(name);
      list.push({
        url: this._absolute(m[1]),
        number: number,
        relative: both ? Number(both[1]) : 0,
        absolute: both ? Number(both[2]) : 0,
        title: name,
      });
    }
    if (list.length === 0) throw new Error("no episodes listed");
    return list;
  }

  // The players of an episode page for one server: { server, target, label }, English ones
  // first; players with Indonesian subtitles only are left out (they would pass as English).
  async _players(html, pageUrl, wanted) {
    const options = [];
    const re = /<option[^>]*value="([^"]+)"[^>]*>([\s\S]*?)<\/option>/g;
    let m;
    while ((m = re.exec(html))) options.push({ value: this._unescapeBody(m[1]), label: this._plain(m[2]) });
    // Other sites give each player as a button: `data-server="…" data-embed="<base64 iframe>"`.
    const buttons = /<a[^>]*data-embed="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    while ((m = buttons.exec(html))) options.push({ value: m[1], label: this._plain(m[2]) });

    // A player on a page of its own (`…/v/2/`) is loaded only when its label names the server
    // asked for, or when no label names any known server.
    const names = { "OK.ru": /ok\.?\s*ru/i, Rumble: /rumb/i };
    const named = options.some(function (o) { return names["OK.ru"].test(o.label) || names.Rumble.test(o.label); });
    const players = [];
    for (const option of options) {
      let embed = "";
      if (/^https?:\/\//i.test(option.value)) {
        if (option.value.indexOf(this.base) !== 0) continue;
        if (named && names[wanted] && !names[wanted].test(option.label)) continue;
        try {
          embed = await this._page(option.value, pageUrl);
        } catch (error) {
          continue;
        }
        const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(embed) || /<div id="pembed"[^>]*>([\s\S]*?)<\/div>/.exec(embed);
        if (box) embed = box[1];
      } else {
        try {
          embed = atob(option.value.replace(/\s+/g, ""));
        } catch (error) {
          continue;
        }
      }
      const player = this._identify(embed);
      if (player) {
        player.label = option.label;
        players.push(player);
      }
    }
    if (players.length === 0) {
      const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(html);
      const player = box ? this._identify(box[1]) : null;
      if (player) players.push(player);
    }
    // English subtitles first; players with Indonesian subtitles only come last.
    const rank = function (p) {
      const label = String(p.label || "");
      if (/eng|multi|all\s*sub/i.test(label)) return 0;
      if (/indo|indonesia/i.test(label)) return 2;
      return 1;
    };
    const kept = players.filter(function (p) { return p.server === wanted && rank(p) < 2; });
    kept.sort(function (a, b) { return rank(a) - rank(b); });
    return kept;
  }

  _identify(embed) {
    const text = String(embed);
    let m = /ok\.ru\/videoembed\/(\d+)/.exec(text);
    if (m) return { server: "OK.ru", target: m[1] };
    m = /rumble\.com\/embed\/([\w]+)/.exec(text);
    if (m) return { server: "Rumble", target: m[1] };
    return null;
  }

  // ---------------------------------------------------------------- video hosts

  async _okru(id) {
    const html = await this._page("https://ok.ru/videoembed/" + id, "https://ok.ru/");
    const m = /data-options="([^"]+)"/.exec(html);
    if (!m) throw new Error("OK.ru video unavailable");
    const options = JSON.parse(this._unescapeBody(m[1]));
    let meta = options && options.flashvars && options.flashvars.metadata;
    if (typeof meta === "string") meta = JSON.parse(meta);
    if (!meta) throw new Error("OK.ru video unavailable");
    const sources = [];
    if (meta.hlsManifestUrl) sources.push({ url: meta.hlsManifestUrl, type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] });
    const order = ["ultra", "quad", "full", "hd", "sd", "low"];
    const names = { ultra: "2160p", quad: "1440p", full: "1080p", hd: "720p", sd: "480p", low: "360p" };
    const videos = (meta.videos || []).filter(function (v) { return v && v.url && order.indexOf(v.name) >= 0; });
    videos.sort(function (a, b) { return order.indexOf(a.name) - order.indexOf(b.name); });
    for (const v of videos.slice(0, 2)) sources.push({ url: v.url, type: "mp4", quality: names[v.name], label: "English hard sub", subtitles: [] });
    if (sources.length === 0) throw new Error("OK.ru has no stream for this video");
    return { server: "OK.ru", headers: { Referer: "https://ok.ru/" }, videoSources: sources };
  }

  async _rumble(id, pageUrl) {
    const html = this._unescapeBody(await this._page("https://rumble.com/embed/" + id + "/", pageUrl));
    const m = /"hls":\{(?:"auto":\{)?"url":"([^"]+\.m3u8[^"]*)"/.exec(html);
    if (!m) throw new Error("Rumble video unavailable");
    return {
      server: "Rumble",
      headers: { Referer: "https://rumble.com/" },
      videoSources: [{ url: m[1], type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] }],
    };
  }

  // ---------------------------------------------------------------- seasons

  // Episodes of the seasons before this one on AniList (prequels of the same kind, followed
  // back), kept for the session. AniList answers relations two levels deep only, so each request
  // walks two seasons back. Throws when AniList cannot tell, so the site's own numbers are used
  // instead of a guess.
  async _earlierEpisodes(anilistId) {
    const first = Number(anilistId);
    if (!(first > 0)) throw new Error("no AniList id");
    this._earlierKnown = this._earlierKnown || {};
    this._earlierFailed = this._earlierFailed || {};
    if (this._earlierKnown[first] !== undefined) return this._earlierKnown[first];
    if (this._earlierFailed[first] && Date.now() - this._earlierFailed[first] < 60000) {
      throw new Error("AniList did not answer a moment ago");
    }
    try {
      const total = await this._askEarlier(first);
      this._earlierKnown[first] = total;
      return total;
    } catch (error) {
      this._earlierFailed[first] = Date.now();
      throw error;
    }
  }

  async _askEarlier(first) {

    const isPrequel = function (e) {
      return e.relationType === "PREQUEL" && e.node && e.node.type === "ANIME" && /^(TV|ONA|TV_SHORT)$/.test(e.node.format || "");
    };
    const edges = "relations{edges{relationType node{id type format episodes ";
    const query = "query($id:Int){Media(id:$id){id " + edges + edges + "id}}}}}}}}";
    let id = first;
    let total = 0;
    for (let request = 0; request < 5; request++) {
      const response = await fetch("https://graphql.anilist.co", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ query: query, variables: { id: id } }),
      });
      if (!response.ok) throw new Error("AniList answered HTTP " + response.status);
      const data = JSON.parse(String(await response.text()));
      const media = data && data.data && data.data.Media;
      if (!media || !media.relations) throw new Error("AniList has no entry " + id);

      const one = (media.relations.edges || []).find(isPrequel);
      if (!one) return total;
      if (!(one.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += one.node.episodes;
      if (!one.node.relations) throw new Error("AniList left out a season's relations");
      const two = (one.node.relations.edges || []).find(isPrequel);
      if (!two) return total;
      if (!(two.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += two.node.episodes;
      // Its own prequels were not asked for: the next request starts from it.
      id = two.node.id;
    }
    throw new Error("too many seasons before this one");
  }

  _season(media) {
    let number = 1;
    let base = "";
    for (const title of [media.englishTitle, media.romajiTitle]) {
      if (typeof title !== "string" || !title) continue;
      const n = this._seasonOf(title);
      if (n > number) number = n;
      if (!base) base = this._withoutSeason(title);
    }
    return { number: number, base: base };
  }

  // Season a title names: "Season 2", "2nd Season", "S2", a trailing " 2"; 0 when it names none.
  _seasonOf(title) {
    const t = String(title).toLowerCase();
    let m = /\bseason\s*(\d+)\b/.exec(t) || /\b(\d+)(?:st|nd|rd|th)\s+season\b/.exec(t) || /\bs(\d+)\b/.exec(t);
    if (m) return Number(m[1]);
    m = /\s(\d)\s*$/.exec(t.replace(/\(\d{4}\)/g, "").replace(/\[[^\]]*\]/g, "").trim());
    if (m) return Number(m[1]);
    return 0;
  }

  _withoutSeason(title) {
    return String(title)
      .replace(/\b(?:season\s*\d+|\d+(?:st|nd|rd|th)\s+season|s\d+|part\s*\d+|cour\s*\d+)\b/gi, " ")
      .replace(/\s\d\s*$/, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _sameShow(siteTitle, base) {
    const words = function (s) {
      return String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").split(" ").filter(function (w) {
        return w && ["the", "of", "a", "3d", "season"].indexOf(w) < 0;
      });
    };
    const want = words(base);
    const got = words(this._cleanTitle(siteTitle));
    if (want.length === 0 || want.length !== got.length) return false;
    return want.every(function (w) { return got.indexOf(w) >= 0; });
  }

  _firstNumber(list) {
    let first = Infinity;
    for (const ep of list) if (ep.number < first) first = ep.number;
    return first;
  }

  _lastNumber(list) {
    let last = 0;
    for (const ep of list) if (ep.number > last) last = ep.number;
    return last;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const add = (title) => {
      if (typeof title !== "string") return;
      const plain = this._withoutSeason(title.replace(/\(\d{4}\)/g, " ").replace(/[^\w\s'-]+/g, " ")).replace(/\s+/g, " ").trim();
      if (plain && queries.indexOf(plain) < 0) queries.push(plain);
    };
    // The app calls search once per title it knows, so the title it gives is the one searched.
    add(opts && opts.query);
    if (queries.length === 0) {
      add(media.englishTitle);
      add(media.romajiTitle);
    }
    // These sites find only titles holding every word searched ("Tang Clan" misses "Tang Sect"):
    // the first words alone come next, and the app picks the right hit among them.
    const words = (queries[0] || "").split(" ");
    if (words.length > 3) add(words.slice(0, 3).join(" "));
    return queries.slice(0, 2);
  }

  // A site title without what only the site adds: "(2023)", "[Da Zhuzai]", "3D", "Subbed"…
  _cleanTitle(title) {
    return String(title)
      .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
      .replace(/\b(?:3d|subbed|eng(?:lish)?\s*sub|multi(?:ple)?\s*sub(?:titles?)?|subtitle\s*indonesia|indo(?:nesia)?\s*sub)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _leadingNumber(text) {
    const m = /^\s*(\d+(?:\.\d+)?)/.exec(String(text));
    return m ? Number(m[1]) : NaN;
  }

  _path(href) {
    const url = this._absolute(href);
    if (url.indexOf(this.base + "/") !== 0) return "";
    return url.slice(this.base.length + 1).replace(/\/+$/, "");
  }

  _absolute(href) {
    const text = String(href).trim();
    if (/^https?:\/\//i.test(text)) return text.replace(/^http:/i, "https:");
    if (text.indexOf("//") === 0) return "https:" + text;
    return this.base + (text.charAt(0) === "/" ? "" : "/") + text;
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl-bypass", "challenge-platform/h/b/orchestrate", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  async _page(url, referer) {
    const host = this._host(url);
    const headers = {};
    if (referer) headers.Referer = referer;
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (text.length < 20000 && this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
    return text;
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}

// AnimeXin (animexin.dev): Chinese animation (donghua) with English subtitles burnt in, from a site
// built on the AnimeStream WordPress theme. Videos come from OK.ru and Rumble (the sites'
// Dailymotion players are left out: Dailymotion refuses their streams to apps).
//
// Donghua sites often number all seasons in one run (season 2 episode 1 = episode 53). When the
// site has no entry of its own for the season asked, the episodes before it are counted on AniList
// and the shared entry is renumbered, so season 2 episode 45 plays the site's episode 97.

class Provider {
  constructor() {
    this.base = "https://animexin.dev";
  }

  getSettings() {
    return {
      episodeServers: ["OK.ru", "Rumble"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // These sites carry subtitled releases only.
    if (opts && opts.dub) return [];
    const media = (opts && opts.media) || {};
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    let hits = [];
    let failure = null;
    for (const query of queries) {
      try {
        const html = await this._page(this.base + "/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
        for (const hit of this._searchHits(html)) {
          if (!hits.some(function (h) { return h.path === hit.path; })) hits.push(hit);
        }
      } catch (error) {
        failure = error;
      }
      if (hits.length > 0) break;
    }
    if (hits.length === 0 && failure) throw failure;

    // Episodes of the seasons before this one (-1 when AniList could not tell) and this season's
    // own count (0 when unknown): every id carries both, so the episode list can be numbered
    // the way AniList numbers this season.
    const earlier = await this._earlierEpisodes(media.id).catch(function () { return -1; });
    const limit = media.episodeCount > 0 ? media.episodeCount : 0;
    const idOf = (path, shared) => path + "@" + earlier + "@" + limit + "@" + (shared ? 1 : 0);

    const results = [];
    for (const hit of hits) {
      results.push({
        id: idOf(hit.path, false),
        title: this._cleanTitle(hit.title),
        altTitles: [hit.title],
        url: this.base + "/" + hit.path + "/",
        subOrDub: "sub",
        format: /movie/i.test(hit.type || "") ? "MOVIE" : undefined,
      });
    }

    // A later season the site keeps inside one shared entry: offered under the season's own
    // title once the shared entry is seen to go past the earlier seasons.
    const season = this._season(media);
    if (season.number > 1 && !hits.some((h) => this._seasonOf(h.title) === season.number)) {
      if (earlier > 0) {
        for (const hit of hits) {
          if (this._seasonOf(hit.title) !== 0 || /movie/i.test(hit.type || "")) continue;
          if (!this._sameShow(hit.title, season.base)) continue;
          let list;
          try {
            list = await this._episodeList(hit.path);
          } catch (error) {
            continue;
          }
          // All seasons in one run: its numbers go from the earlier seasons into this one (some
          // sites list only their last 50 episodes, so it need not start at 1).
          if (this._firstNumber(list) > earlier || this._lastNumber(list) <= earlier) continue;
          results.unshift({
            id: idOf(hit.path, true),
            title: media.englishTitle || media.romajiTitle || this._cleanTitle(hit.title),
            altTitles: [media.romajiTitle, hit.title].filter(Boolean),
            url: this.base + "/" + hit.path + "/",
            subOrDub: "sub",
          });
          break;
        }
      }
    }
    return results;
  }

  async findEpisodes(id) {
    // `path@earlier@limit@shared`: see search().
    const parts = String(id).split("@");
    const path = parts[0];
    const earlier = parts.length > 1 ? Number(parts[1]) : -1;
    const limit = parts.length > 2 ? Number(parts[2]) || 0 : 0;
    const shared = parts[3] === "1";
    if (!/^[\w\/.-]+$/.test(path)) throw new Error("invalid anime id '" + id + "'");

    const list = await this._episodeList(path);
    // Sites cut seasons in different places, so an absolute number ("Episode 51 [181]") is the
    // safe one, counted against the episodes AniList puts before this season. A list numbered
    // two ways is matched only when every absolute number lies past those episodes; otherwise
    // the site cut its season elsewhere, or AniList counts specials the site leaves out, and
    // which one cannot be told: better no episode from this site than the wrong one.
    const absolutes = list.filter(function (ep) { return ep.absolute > 0; });
    const twoWays = absolutes.some(function (ep) { return ep.absolute !== ep.relative; });
    if (twoWays && earlier < 0) {
      throw new Error("AniList did not answer, so this site's season numbering cannot be checked right now");
    }
    if (twoWays && absolutes.some(function (ep) { return ep.absolute <= earlier; })) {
      throw new Error("this site's season does not line up with AniList's");
    }
    const byAbsolute = twoWays;
    const episodes = [];
    const seen = {};
    for (const ep of list) {
      let number;
      if (byAbsolute && ep.absolute > 0) number = ep.absolute - earlier;
      // The entry added for a later season holds every season, numbered from the first.
      else if (shared && earlier > 0) number = ep.number - earlier;
      else number = ep.relative > 0 ? ep.relative : ep.number;
      if (!(number > 0) || seen[number]) continue;
      if (limit > 0 && number > limit) continue;
      seen[number] = true;
      episodes.push({
        id: ep.url,
        number: number,
        url: ep.url,
        title: ep.title || ("Episode " + number),
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const url = String((episode && (episode.url || episode.id)) || "");
    if (!/^https:\/\//.test(url)) throw new Error("no page for this episode");
    const html = await this._page(url, this.base + "/");
    const wanted = String(server || "OK.ru");
    const players = await this._players(html, url, wanted);
    const matching = players.filter(function (p) { return p.server === wanted; });
    if (matching.length === 0) throw new Error("no " + wanted + " player for this episode");

    let failure = null;
    for (const player of matching) {
      try {
        if (player.server === "OK.ru") return await this._okru(player.target);
        if (player.server === "Rumble") return await this._rumble(player.target, url);
      } catch (error) {
        failure = error;
      }
    }
    throw failure || new Error("no playable " + wanted + " video");
  }

  // ---------------------------------------------------------------- site pages

  _searchHits(html) {
    const hits = [];
    const re = /<article class="bs"[\s\S]*?<\/article>/g;
    let m;
    while ((m = re.exec(html))) {
      const block = m[0];
      const href = /href="([^"]+)"/.exec(block);
      const title = /title="([^"]+)"/.exec(block) || /<h2[^>]*>([\s\S]*?)<\/h2>/.exec(block);
      const type = /<div class="typez[^"]*">([\s\S]*?)<\/div>/.exec(block);
      if (!href || !title) continue;
      const path = this._path(href[1]);
      if (!path) continue;
      // Motion comics share the show's name but are not the show.
      if (/\bcomics?\b|manhua\s*animation/i.test(title[1])) continue;
      hits.push({ path: path, title: this._plain(title[1]), type: type ? this._plain(type[1]) : "" });
    }
    return hits;
  }

  async _episodeList(path) {
    const html = await this._page(this.base + "/" + path + "/", this.base + "/");
    const box = /<div class="eplister">([\s\S]*?)<\/ul>/.exec(html);
    if (!box) throw new Error("no episodes listed");
    const list = [];
    const re = /<li[^>]*>\s*<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(box[1]))) {
      const num = /class="epl-num">([\s\S]*?)<\/div>/.exec(m[2]);
      const title = /class="epl-title">([\s\S]*?)<\/div>/.exec(m[2]);
      const number = num ? this._leadingNumber(this._plain(num[1])) : NaN;
      if (!isFinite(number)) continue;
      const name = title ? this._plain(title[1]) : "";
      // "Episode 51 [181]": 51 in the season, 181 counted from the show's first episode.
      const both = /\bEp(?:isode|isod|s)?\.?\s*0*(\d+)\s*\[0*(\d+)\]/i.exec(name);
      list.push({
        url: this._absolute(m[1]),
        number: number,
        relative: both ? Number(both[1]) : 0,
        absolute: both ? Number(both[2]) : 0,
        title: name,
      });
    }
    if (list.length === 0) throw new Error("no episodes listed");
    return list;
  }

  // The players of an episode page for one server: { server, target, label }, English ones
  // first; players with Indonesian subtitles only are left out (they would pass as English).
  async _players(html, pageUrl, wanted) {
    const options = [];
    const re = /<option[^>]*value="([^"]+)"[^>]*>([\s\S]*?)<\/option>/g;
    let m;
    while ((m = re.exec(html))) options.push({ value: this._unescapeBody(m[1]), label: this._plain(m[2]) });
    // Other sites give each player as a button: `data-server="…" data-embed="<base64 iframe>"`.
    const buttons = /<a[^>]*data-embed="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    while ((m = buttons.exec(html))) options.push({ value: m[1], label: this._plain(m[2]) });

    // A player on a page of its own (`…/v/2/`) is loaded only when its label names the server
    // asked for, or when no label names any known server.
    const names = { "OK.ru": /ok\.?\s*ru/i, Rumble: /rumb/i };
    const named = options.some(function (o) { return names["OK.ru"].test(o.label) || names.Rumble.test(o.label); });
    const players = [];
    for (const option of options) {
      let embed = "";
      if (/^https?:\/\//i.test(option.value)) {
        if (option.value.indexOf(this.base) !== 0) continue;
        if (named && names[wanted] && !names[wanted].test(option.label)) continue;
        try {
          embed = await this._page(option.value, pageUrl);
        } catch (error) {
          continue;
        }
        const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(embed) || /<div id="pembed"[^>]*>([\s\S]*?)<\/div>/.exec(embed);
        if (box) embed = box[1];
      } else {
        try {
          embed = atob(option.value.replace(/\s+/g, ""));
        } catch (error) {
          continue;
        }
      }
      const player = this._identify(embed);
      if (player) {
        player.label = option.label;
        players.push(player);
      }
    }
    if (players.length === 0) {
      const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(html);
      const player = box ? this._identify(box[1]) : null;
      if (player) players.push(player);
    }
    // English subtitles first; players with Indonesian subtitles only come last.
    const rank = function (p) {
      const label = String(p.label || "");
      if (/eng|multi|all\s*sub/i.test(label)) return 0;
      if (/indo|indonesia/i.test(label)) return 2;
      return 1;
    };
    const kept = players.filter(function (p) { return p.server === wanted && rank(p) < 2; });
    kept.sort(function (a, b) { return rank(a) - rank(b); });
    return kept;
  }

  _identify(embed) {
    const text = String(embed);
    let m = /ok\.ru\/videoembed\/(\d+)/.exec(text);
    if (m) return { server: "OK.ru", target: m[1] };
    m = /rumble\.com\/embed\/([\w]+)/.exec(text);
    if (m) return { server: "Rumble", target: m[1] };
    return null;
  }

  // ---------------------------------------------------------------- video hosts

  async _okru(id) {
    const html = await this._page("https://ok.ru/videoembed/" + id, "https://ok.ru/");
    const m = /data-options="([^"]+)"/.exec(html);
    if (!m) throw new Error("OK.ru video unavailable");
    const options = JSON.parse(this._unescapeBody(m[1]));
    let meta = options && options.flashvars && options.flashvars.metadata;
    if (typeof meta === "string") meta = JSON.parse(meta);
    if (!meta) throw new Error("OK.ru video unavailable");
    const sources = [];
    if (meta.hlsManifestUrl) sources.push({ url: meta.hlsManifestUrl, type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] });
    const order = ["ultra", "quad", "full", "hd", "sd", "low"];
    const names = { ultra: "2160p", quad: "1440p", full: "1080p", hd: "720p", sd: "480p", low: "360p" };
    const videos = (meta.videos || []).filter(function (v) { return v && v.url && order.indexOf(v.name) >= 0; });
    videos.sort(function (a, b) { return order.indexOf(a.name) - order.indexOf(b.name); });
    for (const v of videos.slice(0, 2)) sources.push({ url: v.url, type: "mp4", quality: names[v.name], label: "English hard sub", subtitles: [] });
    if (sources.length === 0) throw new Error("OK.ru has no stream for this video");
    return { server: "OK.ru", headers: { Referer: "https://ok.ru/" }, videoSources: sources };
  }

  async _rumble(id, pageUrl) {
    const html = this._unescapeBody(await this._page("https://rumble.com/embed/" + id + "/", pageUrl));
    const m = /"hls":\{(?:"auto":\{)?"url":"([^"]+\.m3u8[^"]*)"/.exec(html);
    if (!m) throw new Error("Rumble video unavailable");
    return {
      server: "Rumble",
      headers: { Referer: "https://rumble.com/" },
      videoSources: [{ url: m[1], type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] }],
    };
  }

  // ---------------------------------------------------------------- seasons

  // Episodes of the seasons before this one on AniList (prequels of the same kind, followed
  // back), kept for the session. AniList answers relations two levels deep only, so each request
  // walks two seasons back. Throws when AniList cannot tell, so the site's own numbers are used
  // instead of a guess.
  async _earlierEpisodes(anilistId) {
    const first = Number(anilistId);
    if (!(first > 0)) throw new Error("no AniList id");
    this._earlierKnown = this._earlierKnown || {};
    this._earlierFailed = this._earlierFailed || {};
    if (this._earlierKnown[first] !== undefined) return this._earlierKnown[first];
    if (this._earlierFailed[first] && Date.now() - this._earlierFailed[first] < 60000) {
      throw new Error("AniList did not answer a moment ago");
    }
    try {
      const total = await this._askEarlier(first);
      this._earlierKnown[first] = total;
      return total;
    } catch (error) {
      this._earlierFailed[first] = Date.now();
      throw error;
    }
  }

  async _askEarlier(first) {

    const isPrequel = function (e) {
      return e.relationType === "PREQUEL" && e.node && e.node.type === "ANIME" && /^(TV|ONA|TV_SHORT)$/.test(e.node.format || "");
    };
    const edges = "relations{edges{relationType node{id type format episodes ";
    const query = "query($id:Int){Media(id:$id){id " + edges + edges + "id}}}}}}}}";
    let id = first;
    let total = 0;
    for (let request = 0; request < 5; request++) {
      const response = await fetch("https://graphql.anilist.co", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ query: query, variables: { id: id } }),
      });
      if (!response.ok) throw new Error("AniList answered HTTP " + response.status);
      const data = JSON.parse(String(await response.text()));
      const media = data && data.data && data.data.Media;
      if (!media || !media.relations) throw new Error("AniList has no entry " + id);

      const one = (media.relations.edges || []).find(isPrequel);
      if (!one) return total;
      if (!(one.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += one.node.episodes;
      if (!one.node.relations) throw new Error("AniList left out a season's relations");
      const two = (one.node.relations.edges || []).find(isPrequel);
      if (!two) return total;
      if (!(two.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += two.node.episodes;
      // Its own prequels were not asked for: the next request starts from it.
      id = two.node.id;
    }
    throw new Error("too many seasons before this one");
  }

  _season(media) {
    let number = 1;
    let base = "";
    for (const title of [media.englishTitle, media.romajiTitle]) {
      if (typeof title !== "string" || !title) continue;
      const n = this._seasonOf(title);
      if (n > number) number = n;
      if (!base) base = this._withoutSeason(title);
    }
    return { number: number, base: base };
  }

  // Season a title names: "Season 2", "2nd Season", "S2", a trailing " 2"; 0 when it names none.
  _seasonOf(title) {
    const t = String(title).toLowerCase();
    let m = /\bseason\s*(\d+)\b/.exec(t) || /\b(\d+)(?:st|nd|rd|th)\s+season\b/.exec(t) || /\bs(\d+)\b/.exec(t);
    if (m) return Number(m[1]);
    m = /\s(\d)\s*$/.exec(t.replace(/\(\d{4}\)/g, "").replace(/\[[^\]]*\]/g, "").trim());
    if (m) return Number(m[1]);
    return 0;
  }

  _withoutSeason(title) {
    return String(title)
      .replace(/\b(?:season\s*\d+|\d+(?:st|nd|rd|th)\s+season|s\d+|part\s*\d+|cour\s*\d+)\b/gi, " ")
      .replace(/\s\d\s*$/, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _sameShow(siteTitle, base) {
    const words = function (s) {
      return String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").split(" ").filter(function (w) {
        return w && ["the", "of", "a", "3d", "season"].indexOf(w) < 0;
      });
    };
    const want = words(base);
    const got = words(this._cleanTitle(siteTitle));
    if (want.length === 0 || want.length !== got.length) return false;
    return want.every(function (w) { return got.indexOf(w) >= 0; });
  }

  _firstNumber(list) {
    let first = Infinity;
    for (const ep of list) if (ep.number < first) first = ep.number;
    return first;
  }

  _lastNumber(list) {
    let last = 0;
    for (const ep of list) if (ep.number > last) last = ep.number;
    return last;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const add = (title) => {
      if (typeof title !== "string") return;
      const plain = this._withoutSeason(title.replace(/\(\d{4}\)/g, " ").replace(/[^\w\s'-]+/g, " ")).replace(/\s+/g, " ").trim();
      if (plain && queries.indexOf(plain) < 0) queries.push(plain);
    };
    // The app calls search once per title it knows, so the title it gives is the one searched.
    add(opts && opts.query);
    if (queries.length === 0) {
      add(media.englishTitle);
      add(media.romajiTitle);
    }
    // These sites find only titles holding every word searched ("Tang Clan" misses "Tang Sect"):
    // the first words alone come next, and the app picks the right hit among them.
    const words = (queries[0] || "").split(" ");
    if (words.length > 3) add(words.slice(0, 3).join(" "));
    return queries.slice(0, 2);
  }

  // A site title without what only the site adds: "(2023)", "[Da Zhuzai]", "3D", "Subbed"…
  _cleanTitle(title) {
    return String(title)
      .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
      .replace(/\b(?:3d|subbed|eng(?:lish)?\s*sub|multi(?:ple)?\s*sub(?:titles?)?|subtitle\s*indonesia|indo(?:nesia)?\s*sub)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _leadingNumber(text) {
    const m = /^\s*(\d+(?:\.\d+)?)/.exec(String(text));
    return m ? Number(m[1]) : NaN;
  }

  _path(href) {
    const url = this._absolute(href);
    if (url.indexOf(this.base + "/") !== 0) return "";
    return url.slice(this.base.length + 1).replace(/\/+$/, "");
  }

  _absolute(href) {
    const text = String(href).trim();
    if (/^https?:\/\//i.test(text)) return text.replace(/^http:/i, "https:");
    if (text.indexOf("//") === 0) return "https:" + text;
    return this.base + (text.charAt(0) === "/" ? "" : "/") + text;
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl-bypass", "challenge-platform/h/b/orchestrate", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  async _page(url, referer) {
    const host = this._host(url);
    const headers = {};
    if (referer) headers.Referer = referer;
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (text.length < 20000 && this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
    return text;
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}

// Lucifer Donghua (.org) (luciferdonghua.org): Chinese animation (donghua) with English subtitles burnt in, from a site
// built on the AnimeStream WordPress theme. Videos come from OK.ru and Rumble (the sites'
// Dailymotion players are left out: Dailymotion refuses their streams to apps).
//
// Donghua sites often number all seasons in one run (season 2 episode 1 = episode 53). When the
// site has no entry of its own for the season asked, the episodes before it are counted on AniList
// and the shared entry is renumbered, so season 2 episode 45 plays the site's episode 97.

class Provider {
  constructor() {
    this.base = "https://luciferdonghua.org";
  }

  getSettings() {
    return {
      episodeServers: ["OK.ru", "Rumble"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // These sites carry subtitled releases only.
    if (opts && opts.dub) return [];
    const media = (opts && opts.media) || {};
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    let hits = [];
    let failure = null;
    for (const query of queries) {
      try {
        const html = await this._page(this.base + "/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
        for (const hit of this._searchHits(html)) {
          if (!hits.some(function (h) { return h.path === hit.path; })) hits.push(hit);
        }
      } catch (error) {
        failure = error;
      }
      if (hits.length > 0) break;
    }
    if (hits.length === 0 && failure) throw failure;

    // Episodes of the seasons before this one (-1 when AniList could not tell) and this season's
    // own count (0 when unknown): every id carries both, so the episode list can be numbered
    // the way AniList numbers this season.
    const earlier = await this._earlierEpisodes(media.id).catch(function () { return -1; });
    const limit = media.episodeCount > 0 ? media.episodeCount : 0;
    const idOf = (path, shared) => path + "@" + earlier + "@" + limit + "@" + (shared ? 1 : 0);

    const results = [];
    for (const hit of hits) {
      results.push({
        id: idOf(hit.path, false),
        title: this._cleanTitle(hit.title),
        altTitles: [hit.title],
        url: this.base + "/" + hit.path + "/",
        subOrDub: "sub",
        format: /movie/i.test(hit.type || "") ? "MOVIE" : undefined,
      });
    }

    // A later season the site keeps inside one shared entry: offered under the season's own
    // title once the shared entry is seen to go past the earlier seasons.
    const season = this._season(media);
    if (season.number > 1 && !hits.some((h) => this._seasonOf(h.title) === season.number)) {
      if (earlier > 0) {
        for (const hit of hits) {
          if (this._seasonOf(hit.title) !== 0 || /movie/i.test(hit.type || "")) continue;
          if (!this._sameShow(hit.title, season.base)) continue;
          let list;
          try {
            list = await this._episodeList(hit.path);
          } catch (error) {
            continue;
          }
          // All seasons in one run: its numbers go from the earlier seasons into this one (some
          // sites list only their last 50 episodes, so it need not start at 1).
          if (this._firstNumber(list) > earlier || this._lastNumber(list) <= earlier) continue;
          results.unshift({
            id: idOf(hit.path, true),
            title: media.englishTitle || media.romajiTitle || this._cleanTitle(hit.title),
            altTitles: [media.romajiTitle, hit.title].filter(Boolean),
            url: this.base + "/" + hit.path + "/",
            subOrDub: "sub",
          });
          break;
        }
      }
    }
    return results;
  }

  async findEpisodes(id) {
    // `path@earlier@limit@shared`: see search().
    const parts = String(id).split("@");
    const path = parts[0];
    const earlier = parts.length > 1 ? Number(parts[1]) : -1;
    const limit = parts.length > 2 ? Number(parts[2]) || 0 : 0;
    const shared = parts[3] === "1";
    if (!/^[\w\/.-]+$/.test(path)) throw new Error("invalid anime id '" + id + "'");

    const list = await this._episodeList(path);
    // Sites cut seasons in different places, so an absolute number ("Episode 51 [181]") is the
    // safe one, counted against the episodes AniList puts before this season. A list numbered
    // two ways is matched only when every absolute number lies past those episodes; otherwise
    // the site cut its season elsewhere, or AniList counts specials the site leaves out, and
    // which one cannot be told: better no episode from this site than the wrong one.
    const absolutes = list.filter(function (ep) { return ep.absolute > 0; });
    const twoWays = absolutes.some(function (ep) { return ep.absolute !== ep.relative; });
    if (twoWays && earlier < 0) {
      throw new Error("AniList did not answer, so this site's season numbering cannot be checked right now");
    }
    if (twoWays && absolutes.some(function (ep) { return ep.absolute <= earlier; })) {
      throw new Error("this site's season does not line up with AniList's");
    }
    const byAbsolute = twoWays;
    const episodes = [];
    const seen = {};
    for (const ep of list) {
      let number;
      if (byAbsolute && ep.absolute > 0) number = ep.absolute - earlier;
      // The entry added for a later season holds every season, numbered from the first.
      else if (shared && earlier > 0) number = ep.number - earlier;
      else number = ep.relative > 0 ? ep.relative : ep.number;
      if (!(number > 0) || seen[number]) continue;
      if (limit > 0 && number > limit) continue;
      seen[number] = true;
      episodes.push({
        id: ep.url,
        number: number,
        url: ep.url,
        title: ep.title || ("Episode " + number),
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const url = String((episode && (episode.url || episode.id)) || "");
    if (!/^https:\/\//.test(url)) throw new Error("no page for this episode");
    const html = await this._page(url, this.base + "/");
    const wanted = String(server || "OK.ru");
    const players = await this._players(html, url, wanted);
    const matching = players.filter(function (p) { return p.server === wanted; });
    if (matching.length === 0) throw new Error("no " + wanted + " player for this episode");

    let failure = null;
    for (const player of matching) {
      try {
        if (player.server === "OK.ru") return await this._okru(player.target);
        if (player.server === "Rumble") return await this._rumble(player.target, url);
      } catch (error) {
        failure = error;
      }
    }
    throw failure || new Error("no playable " + wanted + " video");
  }

  // ---------------------------------------------------------------- site pages

  _searchHits(html) {
    const hits = [];
    const re = /<article class="bs"[\s\S]*?<\/article>/g;
    let m;
    while ((m = re.exec(html))) {
      const block = m[0];
      const href = /href="([^"]+)"/.exec(block);
      const title = /title="([^"]+)"/.exec(block) || /<h2[^>]*>([\s\S]*?)<\/h2>/.exec(block);
      const type = /<div class="typez[^"]*">([\s\S]*?)<\/div>/.exec(block);
      if (!href || !title) continue;
      const path = this._path(href[1]);
      if (!path) continue;
      // Motion comics share the show's name but are not the show.
      if (/\bcomics?\b|manhua\s*animation/i.test(title[1])) continue;
      hits.push({ path: path, title: this._plain(title[1]), type: type ? this._plain(type[1]) : "" });
    }
    return hits;
  }

  async _episodeList(path) {
    const html = await this._page(this.base + "/" + path + "/", this.base + "/");
    const box = /<div class="eplister">([\s\S]*?)<\/ul>/.exec(html);
    if (!box) throw new Error("no episodes listed");
    const list = [];
    const re = /<li[^>]*>\s*<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(box[1]))) {
      const num = /class="epl-num">([\s\S]*?)<\/div>/.exec(m[2]);
      const title = /class="epl-title">([\s\S]*?)<\/div>/.exec(m[2]);
      const number = num ? this._leadingNumber(this._plain(num[1])) : NaN;
      if (!isFinite(number)) continue;
      const name = title ? this._plain(title[1]) : "";
      // "Episode 51 [181]": 51 in the season, 181 counted from the show's first episode.
      const both = /\bEp(?:isode|isod|s)?\.?\s*0*(\d+)\s*\[0*(\d+)\]/i.exec(name);
      list.push({
        url: this._absolute(m[1]),
        number: number,
        relative: both ? Number(both[1]) : 0,
        absolute: both ? Number(both[2]) : 0,
        title: name,
      });
    }
    if (list.length === 0) throw new Error("no episodes listed");
    return list;
  }

  // The players of an episode page for one server: { server, target, label }, English ones
  // first; players with Indonesian subtitles only are left out (they would pass as English).
  async _players(html, pageUrl, wanted) {
    const options = [];
    const re = /<option[^>]*value="([^"]+)"[^>]*>([\s\S]*?)<\/option>/g;
    let m;
    while ((m = re.exec(html))) options.push({ value: this._unescapeBody(m[1]), label: this._plain(m[2]) });
    // Other sites give each player as a button: `data-server="…" data-embed="<base64 iframe>"`.
    const buttons = /<a[^>]*data-embed="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    while ((m = buttons.exec(html))) options.push({ value: m[1], label: this._plain(m[2]) });

    // A player on a page of its own (`…/v/2/`) is loaded only when its label names the server
    // asked for, or when no label names any known server.
    const names = { "OK.ru": /ok\.?\s*ru/i, Rumble: /rumb/i };
    const named = options.some(function (o) { return names["OK.ru"].test(o.label) || names.Rumble.test(o.label); });
    const players = [];
    for (const option of options) {
      let embed = "";
      if (/^https?:\/\//i.test(option.value)) {
        if (option.value.indexOf(this.base) !== 0) continue;
        if (named && names[wanted] && !names[wanted].test(option.label)) continue;
        try {
          embed = await this._page(option.value, pageUrl);
        } catch (error) {
          continue;
        }
        const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(embed) || /<div id="pembed"[^>]*>([\s\S]*?)<\/div>/.exec(embed);
        if (box) embed = box[1];
      } else {
        try {
          embed = atob(option.value.replace(/\s+/g, ""));
        } catch (error) {
          continue;
        }
      }
      const player = this._identify(embed);
      if (player) {
        player.label = option.label;
        players.push(player);
      }
    }
    if (players.length === 0) {
      const box = /<div class="player-embed"[^>]*>([\s\S]*?)<\/div>/.exec(html);
      const player = box ? this._identify(box[1]) : null;
      if (player) players.push(player);
    }
    // English subtitles first; players with Indonesian subtitles only come last.
    const rank = function (p) {
      const label = String(p.label || "");
      if (/eng|multi|all\s*sub/i.test(label)) return 0;
      if (/indo|indonesia/i.test(label)) return 2;
      return 1;
    };
    const kept = players.filter(function (p) { return p.server === wanted && rank(p) < 2; });
    kept.sort(function (a, b) { return rank(a) - rank(b); });
    return kept;
  }

  _identify(embed) {
    const text = String(embed);
    let m = /ok\.ru\/videoembed\/(\d+)/.exec(text);
    if (m) return { server: "OK.ru", target: m[1] };
    m = /rumble\.com\/embed\/([\w]+)/.exec(text);
    if (m) return { server: "Rumble", target: m[1] };
    return null;
  }

  // ---------------------------------------------------------------- video hosts

  async _okru(id) {
    const html = await this._page("https://ok.ru/videoembed/" + id, "https://ok.ru/");
    const m = /data-options="([^"]+)"/.exec(html);
    if (!m) throw new Error("OK.ru video unavailable");
    const options = JSON.parse(this._unescapeBody(m[1]));
    let meta = options && options.flashvars && options.flashvars.metadata;
    if (typeof meta === "string") meta = JSON.parse(meta);
    if (!meta) throw new Error("OK.ru video unavailable");
    const sources = [];
    if (meta.hlsManifestUrl) sources.push({ url: meta.hlsManifestUrl, type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] });
    const order = ["ultra", "quad", "full", "hd", "sd", "low"];
    const names = { ultra: "2160p", quad: "1440p", full: "1080p", hd: "720p", sd: "480p", low: "360p" };
    const videos = (meta.videos || []).filter(function (v) { return v && v.url && order.indexOf(v.name) >= 0; });
    videos.sort(function (a, b) { return order.indexOf(a.name) - order.indexOf(b.name); });
    for (const v of videos.slice(0, 2)) sources.push({ url: v.url, type: "mp4", quality: names[v.name], label: "English hard sub", subtitles: [] });
    if (sources.length === 0) throw new Error("OK.ru has no stream for this video");
    return { server: "OK.ru", headers: { Referer: "https://ok.ru/" }, videoSources: sources };
  }

  async _rumble(id, pageUrl) {
    const html = this._unescapeBody(await this._page("https://rumble.com/embed/" + id + "/", pageUrl));
    const m = /"hls":\{(?:"auto":\{)?"url":"([^"]+\.m3u8[^"]*)"/.exec(html);
    if (!m) throw new Error("Rumble video unavailable");
    return {
      server: "Rumble",
      headers: { Referer: "https://rumble.com/" },
      videoSources: [{ url: m[1], type: "m3u8", quality: "auto", label: "English hard sub", subtitles: [] }],
    };
  }

  // ---------------------------------------------------------------- seasons

  // Episodes of the seasons before this one on AniList (prequels of the same kind, followed
  // back), kept for the session. AniList answers relations two levels deep only, so each request
  // walks two seasons back. Throws when AniList cannot tell, so the site's own numbers are used
  // instead of a guess.
  async _earlierEpisodes(anilistId) {
    const first = Number(anilistId);
    if (!(first > 0)) throw new Error("no AniList id");
    this._earlierKnown = this._earlierKnown || {};
    this._earlierFailed = this._earlierFailed || {};
    if (this._earlierKnown[first] !== undefined) return this._earlierKnown[first];
    if (this._earlierFailed[first] && Date.now() - this._earlierFailed[first] < 60000) {
      throw new Error("AniList did not answer a moment ago");
    }
    try {
      const total = await this._askEarlier(first);
      this._earlierKnown[first] = total;
      return total;
    } catch (error) {
      this._earlierFailed[first] = Date.now();
      throw error;
    }
  }

  async _askEarlier(first) {

    const isPrequel = function (e) {
      return e.relationType === "PREQUEL" && e.node && e.node.type === "ANIME" && /^(TV|ONA|TV_SHORT)$/.test(e.node.format || "");
    };
    const edges = "relations{edges{relationType node{id type format episodes ";
    const query = "query($id:Int){Media(id:$id){id " + edges + edges + "id}}}}}}}}";
    let id = first;
    let total = 0;
    for (let request = 0; request < 5; request++) {
      const response = await fetch("https://graphql.anilist.co", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ query: query, variables: { id: id } }),
      });
      if (!response.ok) throw new Error("AniList answered HTTP " + response.status);
      const data = JSON.parse(String(await response.text()));
      const media = data && data.data && data.data.Media;
      if (!media || !media.relations) throw new Error("AniList has no entry " + id);

      const one = (media.relations.edges || []).find(isPrequel);
      if (!one) return total;
      if (!(one.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += one.node.episodes;
      if (!one.node.relations) throw new Error("AniList left out a season's relations");
      const two = (one.node.relations.edges || []).find(isPrequel);
      if (!two) return total;
      if (!(two.node.episodes > 0)) throw new Error("AniList does not know a season's episode count");
      total += two.node.episodes;
      // Its own prequels were not asked for: the next request starts from it.
      id = two.node.id;
    }
    throw new Error("too many seasons before this one");
  }

  _season(media) {
    let number = 1;
    let base = "";
    for (const title of [media.englishTitle, media.romajiTitle]) {
      if (typeof title !== "string" || !title) continue;
      const n = this._seasonOf(title);
      if (n > number) number = n;
      if (!base) base = this._withoutSeason(title);
    }
    return { number: number, base: base };
  }

  // Season a title names: "Season 2", "2nd Season", "S2", a trailing " 2"; 0 when it names none.
  _seasonOf(title) {
    const t = String(title).toLowerCase();
    let m = /\bseason\s*(\d+)\b/.exec(t) || /\b(\d+)(?:st|nd|rd|th)\s+season\b/.exec(t) || /\bs(\d+)\b/.exec(t);
    if (m) return Number(m[1]);
    m = /\s(\d)\s*$/.exec(t.replace(/\(\d{4}\)/g, "").replace(/\[[^\]]*\]/g, "").trim());
    if (m) return Number(m[1]);
    return 0;
  }

  _withoutSeason(title) {
    return String(title)
      .replace(/\b(?:season\s*\d+|\d+(?:st|nd|rd|th)\s+season|s\d+|part\s*\d+|cour\s*\d+)\b/gi, " ")
      .replace(/\s\d\s*$/, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _sameShow(siteTitle, base) {
    const words = function (s) {
      return String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").split(" ").filter(function (w) {
        return w && ["the", "of", "a", "3d", "season"].indexOf(w) < 0;
      });
    };
    const want = words(base);
    const got = words(this._cleanTitle(siteTitle));
    if (want.length === 0 || want.length !== got.length) return false;
    return want.every(function (w) { return got.indexOf(w) >= 0; });
  }

  _firstNumber(list) {
    let first = Infinity;
    for (const ep of list) if (ep.number < first) first = ep.number;
    return first;
  }

  _lastNumber(list) {
    let last = 0;
    for (const ep of list) if (ep.number > last) last = ep.number;
    return last;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const add = (title) => {
      if (typeof title !== "string") return;
      const plain = this._withoutSeason(title.replace(/\(\d{4}\)/g, " ").replace(/[^\w\s'-]+/g, " ")).replace(/\s+/g, " ").trim();
      if (plain && queries.indexOf(plain) < 0) queries.push(plain);
    };
    // The app calls search once per title it knows, so the title it gives is the one searched.
    add(opts && opts.query);
    if (queries.length === 0) {
      add(media.englishTitle);
      add(media.romajiTitle);
    }
    // These sites find only titles holding every word searched ("Tang Clan" misses "Tang Sect"):
    // the first words alone come next, and the app picks the right hit among them.
    const words = (queries[0] || "").split(" ");
    if (words.length > 3) add(words.slice(0, 3).join(" "));
    return queries.slice(0, 2);
  }

  // A site title without what only the site adds: "(2023)", "[Da Zhuzai]", "3D", "Subbed"…
  _cleanTitle(title) {
    return String(title)
      .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
      .replace(/\b(?:3d|subbed|eng(?:lish)?\s*sub|multi(?:ple)?\s*sub(?:titles?)?|subtitle\s*indonesia|indo(?:nesia)?\s*sub)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  _leadingNumber(text) {
    const m = /^\s*(\d+(?:\.\d+)?)/.exec(String(text));
    return m ? Number(m[1]) : NaN;
  }

  _path(href) {
    const url = this._absolute(href);
    if (url.indexOf(this.base + "/") !== 0) return "";
    return url.slice(this.base.length + 1).replace(/\/+$/, "");
  }

  _absolute(href) {
    const text = String(href).trim();
    if (/^https?:\/\//i.test(text)) return text.replace(/^http:/i, "https:");
    if (text.indexOf("//") === 0) return "https:" + text;
    return this.base + (text.charAt(0) === "/" ? "" : "/") + text;
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl-bypass", "challenge-platform/h/b/orchestrate", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  async _page(url, referer) {
    const host = this._host(url);
    const headers = {};
    if (referer) headers.Referer = referer;
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (text.length < 20000 && this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
    return text;
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}
